query DiseaseRecord($diseaseId: String!) {
  disease(efoId: $diseaseId) {
    id
    name
    description
    dbXRefs
    synonyms { relation terms }
    isTherapeuticArea
    therapeuticAreas { id name }
    parents { id name }
    children { id name }
    ancestors
    descendants
    obsoleteTerms
  }
}
